var MAINS={Beef:'beef|steak|brisket|sirloin|ribeye|chuck',Chicken:'chicken',Pork:'pork|bacon|ham|sausage',Turkey:'turkey',Lamb:'lamb',Fish:'fish|salmon|tuna|cod|tilapia|trout|halibut',Shellfish:'shrimp|prawns?|crab|lobster|scallops?|clams?|mussels?',Eggs:'eggs?',Tofu:'tofu|tempeh',Beans:'beans?|lentils?|chickpeas?'};
