function render(){var q=($('q')&&$('q').value||'').toLowerCase().trim(), sort=($('sort')&&$('sort').value)||'updated'; var counts={};state.recipes.forEach(function(r){(r.cats||[]).forEach(function(c){counts[c]=(counts[c]||0)+1})}); var un=state.recipes.filter(function(r){return !(r.cats||[]).some(function(c){return state.cats.indexOf(c)>-1})}).length; state.sel=state.sel.filter(function(c){return c==='Uncategorized'?un>0:state.cats.indexOf(c)>-1}); var on=function(c){return state.sel.indexOf(c)>-1}; var h='<button class="cat '+(!state.sel.length?'on':'')+'" data-c="">All <span>'+state.recipes.length+'</span></button>'; state.cats.forEach(function(c){h+='<button class="cat '+(on(c)?'on':'')+'" data-c="'+esc(c)+'">'+esc(c)+' <span>'+(counts[c]||0)+'</span></button>'}); if(un)h+='<button class="cat '+(on('Uncategorized')?'on':'')+'" data-c="Uncategorized">Uncategorized <span>'+un+'</span></button>'; if(state.sel.length>1)h+='<button class="cat mode" data-mode="1">Match: '+(state.mode==='all'?'all':'any')+'</button>'; $('cats').innerHTML=h; var mc={};Object.keys(MAINS).forEach(function(m){mc[m]=state.recipes.filter(function(r){return hasMain(r,m)}).length}); var ks=Object.keys(mc).filter(function(m){return mc[m]>0||state.mains.indexOf(m)>-1}).sort(); $('chips').innerHTML=ks.length?'<button class="chip '+(!state.mains.length?'on':'')+'" data-m="">Any main</button>'+ks.map(function(m){return '<button class="chip '+(state.mains.indexOf(m)>-1?'on':'')+'" data-m="'+esc(m)+'">'+esc(m)+' ('+mc[m]+')</button>'}).join('')+(state.mains.length>1?'<button class="chip mode" data-mode="1" title="Require all selected mains, or any one of them">Match: '+(state.mainMode==='all'?'all':'any')+'</button>':''):'';
  var useSearchFn=(typeof searchMatch==='function'); var rs=state.recipes.filter(function(r){var inCat=matches(r); if(!passFilters(r))return false; var okSearch; if(!q){okSearch=true} else if(useSearchFn){okSearch=searchMatch(r,q)} else {var hay=(r.title+' '+r.ing.join(' ')+' '+r.steps.join(' ')+' '+r.notes+' '+(r.tags||[]).join(' ')+' '+r.nutrition).toLowerCase(); okSearch=(hay+' '+getMain(r).join(' ').toLowerCase()).indexOf(q.toLowerCase())>-1} return inCat&&matchesMains(r)&&okSearch}); rs.sort(function(a,b){if(sort==='title')return a.title.localeCompare(b.title); if(sort==='rating')return (b.rating||0)-(a.rating||0)||b.updated-a.updated; if(sort==='fav')return (b.fav?1:0)-(a.fav?1:0)||b.updated-a.updated; return (b.updated||0)-(a.updated||0)});
  $('list').innerHTML=rs.length?rs.map(function(r){var meta=[r.servings,r.time,r.difficulty].filter(Boolean).join(' ? '); var badges=[]; if(r.rating)badges.push('?'+r.rating); (r.tags||[]).slice(0,3).forEach(function(t){badges.push('#'+t)}); var selExp=state.exportMode&&state.exportSel&&state.exportSel[r.id]; var selBulk=state.bulkMode&&state.selIds&&state.selIds[r.id]; var cardSel=selExp||selBulk; return '<button class="card" data-id="'+r.id+'"'+(cardSel?' style="outline:2px solid var(--accent,#2a7)"':'')+'>'+(state.exportMode?'<div class="star">'+(selExp?'?':'?')+'</div>':(r.fav?'<div class="star">?</div>':''))+'<div class="tag">'+esc(catLabel(r))+'</div><h3>'+esc(r.title)+'</h3>'+ (meta?'<div class="meta">'+esc(meta)+'</div>':'')+(badges.length?'<div class="badges">'+badges.map(function(b){return '<span class="badge">'+esc(b)+'</span>'}).join('')+'</div>':'')+'<p>'+r.ing.length+' ingredients, '+r.steps.length+' steps</p>'+(state.bulkMode?'<div class="small" style="margin-top:6px">'+(selBulk?'&#10003; selected':'Click to select')+'</div>':'')+'</button>'}).join(''):'<div class="empty" style="grid-column:1/-1">'+(state.recipes.length?'No recipes match.':'No recipes yet.')+'</div>'; if($('listInfo'))$('listInfo').textContent='Showing '+rs.length+' of '+state.recipes.length+' recipes'; try{if(typeof renderBulkBar==='function')renderBulkBar()}catch(e){} updateStorageInfo(); try{if(typeof renderCookable==='function')renderCookable()}catch(e){}}
