function addToShop(r,factor){if(!state.shopDone)state.shopDone={'__items__':[]}; if(!state.shopDone['__items__'])state.shopDone['__items__']=[]; var existing=state.shopDone['__items__'].slice(); (r.ing||[]).forEach(function(i){var t=fmtIng(i,factor||1).trim(); if(!t)return; existing.push({key:normItemKey(t)||t.toLowerCase(),text:t,done:false,aisle:guessAisle(t)})}); state.shopDone['__items__']=mergeShopItems(existing); save(); renderShopUI()}
function buildShopFromPlan(ids,opts){ids=ids||state.plan; opts=opts||{}; if(!ids||!ids.length){toast('No recipes to add'); return} var existing=(state.shopDone['__items__']||[]).slice(); ids.forEach(function(id){var r=state.recipes.find(function(x){return x.id===id}); if(!r)return; (r.ing||[]).forEach(function(i){var t=fmtIng(i,1); existing.push({key:normItemKey(t)||t.toLowerCase(),text:t,done:false,aisle:guessAisle(i)})});}); var merged=mergeShopItems(existing); var have={}; (state.pantry||[]).forEach(function(p){if(p&&p.have)have[pantryKey(p.name)]=1}); merged=merged.filter(function(it){return !have[pantryKey(it.text)]}); state.shopDone['__items__']=merged; save(); renderShopUI(); logChange('shop','Shopping list','Added '+ids.length+' recipe(s) ('+merged.length+' items total)'); toast('Added '+ids.length+' recipe(s) to shopping list')}
