function openHistory(){ $('trashList').innerHTML=state.trash.length?state.trash.map(function(r,i){return '<div class="itemrow"><div style="flex:1"><strong>'+esc(r.title)+'</strong></div><button data-undo="'+i+'">Restore</button></div>'}).join(''):'<div class="small">Trash empty.</div>'; $('trashList').onclick=function(e){var b=e.target.closest('button[data-undo]'); if(!b)return; var r=state.trash.splice(+b.dataset.undo,1)[0]; if(r){state.recipes.unshift(norm(r)); save(); render(); openHistory(); toast('Restored')}}; $('histList').innerHTML=state.history.length?state.history.slice().reverse().map(function(h){return '<div class="itemrow"><div style="flex:1"><strong>'+esc(h.title||'Import')+'</strong><div class="small">'+esc(h.when?new Date(h.when).toLocaleString():'')+(h.note?' ? '+esc(h.note):'')+'</div></div></div>'}).join(''):'<div class="small">No history.</div>'; var ch=document.getElementById('chgList'); if(ch){var cl=(state.changelog||[]).slice().reverse(); ch.innerHTML=cl.length?cl.slice(0,100).map(function(c){return '<div class="itemrow"><div style="flex:1"><strong>'+esc(c.type||'change')+'</strong> '+esc(c.title||'')+'<div class="small">'+esc(c.when?new Date(c.when).toLocaleString():'')+(c.note?' ? '+esc(c.note):'')+'</div></div></div>'}).join(''):'<div class="small">No changes logged.</div>';} try{var kl=document.getElementById('cookLogList'); if(kl){var entries=[]; (state.recipes||[]).forEach(function(r){(r.cookLog||[]).forEach(function(c){entries.push({when:c.when,title:r.title,note:c.note})})}); entries.sort(function(a,b){return (b.when||0)-(a.when||0)}); kl.innerHTML=entries.length?entries.slice(0,50).map(function(c){return '<div class="itemrow"><div style="flex:1"><strong>'+esc(c.title)+'</strong><div class="small">'+esc(new Date(c.when).toLocaleString())+(c.note?(' ? '+esc(c.note)):'')+'</div></div></div>'}).join(''):'<div class="small">No cooking logged yet.</div>'}}catch(e){} $('dHistory').showModal();}
$('histClose').onclick=function(){$('dHistory').close()}; $('histClear').onclick=function(){state.history=[]; save(); openHistory()};

function openEdit(id,draft){var r=id?state.recipes.find(function(x){return x.id===id}):(draft||null); state.editId=id||null; state.editDraft=id?null:(draft||null); $('editTitle').textContent=id?'Edit recipe':(draft&&draft._review?'Review imported recipe':'New recipe'); $('fTitle').value=r?r.title||'':''; var pre=state.sel.filter(function(c){return state.cats.indexOf(c)>-1}); catChecks($('fCatBox'),r&&r.cats&&r.cats.length?r.cats:(pre.length?pre:state.cats.slice(0,1))); $('fServings').value=r?r.servings||'':''; $('fTime').value=r?r.time||'':''; $('fDifficulty').value=r?r.difficulty||'':''; $('fRating').value=r?(r.rating||0):0; $('fTags').value=r?(r.tags||[]).join(', '):''; $('fFav').checked=!!(r&&r.fav); $('fMain').value=r?getMain(r).join(', '):''; $('fIng').value=r?(r.ing||[]).join('\n'):''; $('fSteps').value=r?(r.steps||[]).join('\n'):''; $('fEquip').value=r?(r.equip||[]).join('\n'):''; $('fNutrition').value=r?r.nutrition||'':''; $('fNotes').value=r?r.notes||'':''; $('fSource').value=r?r.src||'':''; var d=findDup(r||{title:$('fTitle').value}); setStatus('dupWarn', d?('Possible duplicate: "'+d.r.title+'". Save will prompt to merge/replace/keep both.'):'', d?'err':''); $('dEdit').showModal(); $('fTitle').focus();}
