function mergeInto(targetId){var others=state.recipes.filter(function(r){return r.id!==targetId}); if(!others.length){toast('No other recipes');return} var name=prompt('Merge content FROM which recipe? (type part of its title)'); if(!name)return; var src=others.find(function(r){return r.title.toLowerCase().indexOf(name.toLowerCase())>-1}); if(!src){toast('No match');return} var tgt=state.recipes.find(function(r){return r.id===targetId}); if(!tgt||!src)return; tgt.ing=tgt.ing.concat(src.ing.filter(function(x){return tgt.ing.indexOf(x)<0})); tgt.steps=tgt.steps.concat(src.steps.filter(function(x){return tgt.steps.indexOf(x)<0})); tgt.notes=(tgt.notes?tgt.notes+'\n':'')+'Merged from '+src.title+(src.notes?('\n'+src.notes):''); tgt.updated=now(); save(); render(); openView(targetId); toast('Merged from "'+src.title+'"')}

async function estimateNutrition(r){if(!aiCfg().key){toast('Add OpenRouter key in AI settings'); return} try{toast('Estimating nutrition…'); var data=await aiRequest({model:(aiCfg().model||DEFMODEL),temperature:0,messages:[{role:'system',content:'Estimate nutrition approximately. Reply ONLY JSON: {"nutrition":"short text per serving or total, include kcal and macros if possible, note it is an estimate"}'},{role:'user',content:'Recipe: '+r.title+'\nServings: '+(r.servings||'unknown')+'\nIngredients:\n'+r.ing.join('\n')}]}); var txt=(data.choices&&data.choices[0]&&data.choices[0].message&&data.choices[0].message.content)||''; var o=parseAiJson(txt); if(o.nutrition){r.nutrition=o.nutrition; r.updated=now(); save(); render(); if($('dView').open)openView(r.id); if($('dEdit').open)$('fNutrition').value=r.nutrition; toast('Nutrition estimate added (approximate)')} }catch(e){toast(e.message||'Nutrition estimate failed')}}

