function flat(x){if(typeof x==='string')return [x]; if(Array.isArray(x))return x.reduce(function(a,y){return a.concat(flat(y))},[]); if(x&&x.itemListElement)return flat(x.itemListElement); return x&&(x.text||x.name)?[x.text||x.name]:[]}
