function fromObj(o){if(!o||typeof o!=='object')return null; var title=pick(o,['title','name']); if(!title)return null; var ing=pick(o,['ing','ingredients','recipeIngredient'])||[]; var st=pick(o,['steps','recipeInstructions','instructions'])||[]; if(typeof ing==='string')ing=lines(ing); if(typeof st==='string')st=lines(st); st=flat(st).map(function(x){return String(x).trim()}).filter(Boolean); var y=pick(o,['servings','yield','recipeYield']); if(Array.isArray(y))y=y[0]; var prep=isoDur(pick(o,['prepTime'])),cook=isoDur(pick(o,['cookTime'])),total=isoDur(pick(o,['totalTime','time'])); var t=[]; if(prep)t.push('Prep '+prep); if(cook)t.push('Cook '+cook); if(!t.length&&total)t.push(total); var img=pickImage(o); return norm({id:uid(),title:String(title).trim(),cats:arr(pick(o,['cats','cat','category','recipeCategory'])),tags:arr(pick(o,['tags','keywords'])),ing:[].concat(ing).map(function(x){return String(x).trim()}).filter(Boolean),steps:st,equip:arr(pick(o,['equipment','tool'])),nutrition:String(pick(o,['nutrition'])||''),notes:String(pick(o,['notes','description'])||'').trim(),servings:y?String(y).trim():'',time:t.join(', '),src:String(pick(o,['src','url','source'])||'').trim(),difficulty:pick(o,['difficulty'])||'',rating:pick(o,['rating'])||0,fav:!!pick(o,['fav','favorite']),_imageUrl:img||''})}
