function recipeSummary(r){if(!r)return {}; return {title:r.title||'',servings:r.servings||'',time:r.time||'',difficulty:r.difficulty||'',categories:(r.cats||[]).join(', '),tags:(r.tags||[]).join(', '),ingredients:(r.ing||[]).join('\n'),steps:(r.steps||[]).join('\n'),equipment:(r.equip||[]).join('\n'),notes:r.notes||'',source:r.src||'',nutrition:r.nutrition||''}}
function diffRows(a,b){var A=recipeSummary(a), B=recipeSummary(b); var keys=[['Title','title'],['Servings','servings'],['Time','time'],['Difficulty','difficulty'],['Categories','categories'],['Tags','tags'],['Ingredients','ingredients'],['Steps','steps'],['Equipment','equipment'],['Nutrition','nutrition'],['Notes','notes'],['Source','source']]; return keys.map(function(k){var av=A[k[1]]||'', bv=B[k[1]]||''; return {label:k[0],a:av,b:bv,same:String(av).trim()===String(bv).trim()}})}
function renderDupCompare(existing,incoming){var rows=diffRows(existing,incoming); var h='<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px"><div><strong>Existing in Recipe Box</strong></div><div><strong>Imported recipe</strong></div></div>'; h+='<table style="width:100%;border-collapse:collapse;font-size:13px"><thead><tr><th style="text-align:left;padding:6px;border-bottom:1px solid #ddd;width:16%">Field</th><th style="text-align:left;padding:6px;border-bottom:1px solid #ddd;width:42%">Existing</th><th style="text-align:left;padding:6px;border-bottom:1px solid #ddd;width:42%">Imported</th></tr></thead><tbody>';
  rows.forEach(function(r){var bg=r.same?'':'background:rgba(255,200,0,.12)'; h+='<tr style="'+bg+'"><td style="vertical-align:top;padding:6px;border-bottom:1px solid #eee"><strong>'+esc(r.label)+'</strong>'+(!r.same?' <span class="small">(different)</span>':'')+'</td><td style="vertical-align:top;padding:6px;border-bottom:1px solid #eee;white-space:pre-wrap">'+esc(r.a||'(empty)')+'</td><td style="vertical-align:top;padding:6px;border-bottom:1px solid #eee;white-space:pre-wrap">'+esc(r.b||'(empty)')+'</td></tr>'}); h+='</tbody></table>'; return h}
function nameDupTitle(base){var t=(base||'').trim()||'Untitled recipe'; var n=1, cand=t+' (imported)'; while(state.recipes.some(function(r){return (r.title||'').toLowerCase()===cand.toLowerCase()})){n++; cand=t+' (imported '+n+')'} return cand}
function resolveDuplicate(existing,incoming){return new Promise(function(resolve){var dlg=document.getElementById('dDup'); if(!dlg){resolve({action:'keep_both'}); return}
  document.getElementById('dupBody').innerHTML=renderDupCompare(existing,incoming);
  var ren=document.getElementById('dupRename'); ren.value=nameDupTitle(incoming.title||existing.title||'');
  function cleanup(){document.getElementById('dupKeepExisting').onclick=null; document.getElementById('dupKeepImported').onclick=null; document.getElementById('dupKeepBoth').onclick=null; document.getElementById('dupCancel').onclick=null; dlg.close();}
  document.getElementById('dupKeepExisting').onclick=function(){cleanup(); resolve({action:'keep_existing'})};
  document.getElementById('dupKeepImported').onclick=function(){cleanup(); resolve({action:'keep_imported'})};
  document.getElementById('dupKeepBoth').onclick=function(){var name=(ren.value||'').trim()||nameDupTitle(incoming.title||''); cleanup(); resolve({action:'keep_both',rename:name})};
  document.getElementById('dupCancel').onclick=function(){cleanup(); resolve({action:'cancel'})};
  dlg.showModal();
})}

function mapCats(list){list=arr(list); var out=[]; list.forEach(function(c){var x=c.trim(); if(!x)return; var exact=state.cats.find(function(k){return k.toLowerCase()===x.toLowerCase()}); if(exact){if(out.indexOf(exact)<0)out.push(exact);return} var part=state.cats.find(function(k){return k.toLowerCase().indexOf(x.toLowerCase())>-1||x.toLowerCase().indexOf(k.toLowerCase())>-1}); if(part&&out.indexOf(part)<0)out.push(part)}); return out}
async function addImported(list,defCats,meta){var n=0,dups=[]; for(var i=0;i<(list||[]).length;i++){var r=list[i]; if(!r)continue; norm(r); r.cats=mapCats(r.cats); if(!r.cats.length)r.cats=(defCats||[]).slice(); r.cats.forEach(function(c){if(state.cats.indexOf(c)<0)state.cats.push(c)}); var d=findDup(r); if(d){dups.push(r.title+' ~ '+d.r.title); var res=await resolveDuplicate(d.r,r); if(res.action==='keep_existing'||res.action==='cancel'){continue;} if(res.action==='keep_imported'){Object.assign(d.r,r,{id:d.r.id,created:d.r.created,updated:now()}); save(); n++; continue;} if(res.action==='keep_both'){r.title=res.rename||nameDupTitle(r.title); r.id=uid(); r.created=r.updated=now(); state.recipes.push(norm(r)); save(); n++; continue;} } state.recipes.push(r); n++; save();} render(); if(meta) state.history.push({when:now(),title:meta.title||'Import',note:(n+' saved')+(dups.length?('; duplicates handled: '+dups.length):'')}); save(); return {n:n,dups:dups}}

async function fetchWithTimeout(url,ms,opts){var ctrl=new AbortController(),timer=setTimeout(function(){ctrl.abort()},ms||15000); try{var res=await fetch(url,Object.assign({signal:ctrl.signal},opts||{})); clearTimeout(timer); return res}catch(e){clearTimeout(timer); throw e}}
function looksBlockedPage(text,url){var t=String(text||'').slice(0,4000).toLowerCase(); if(/warning:\s*target url returned error 403/.test(t))return true; if(/this site is experiencing a problem/.test(t)&&/reference id/.test(t))return true; if(/access denied|request blocked|temporarily unavailable|are you a robot|verify you are human|attention required|cf-error-details|captcha|cloudflare/.test(t)&&t.length<12000)return true; return false}
/* Bases for the server-side import fetch. The Recipe Box server fetches pages
   from the same network as the user, so sites that block public relay IPs still
   load. Prefer the origin that served this page, then a configured sync server. */
function importProxyBases(){
  var out=[], seen={};
  function add(u){
    u=String(u||'').replace(/\/+$/,'');
    if(!u||seen[u])return;
    // A secure page cannot call an http endpoint, so skip those.
    if(location.protocol==='https:'&&/^http:/i.test(u))return;
    seen[u]=1; out.push(u);
  }
  try{add(location.origin+'/api/recipebox')}catch(e){}
  try{
    var raw=String((syncCfg()||{}).url||'').replace(/\/+$/,'');
    if(/^https?:\/\//i.test(raw)){
      var api=/\/(api\/)?recipebox$/i.test(raw)?raw:(raw+'/api/recipebox');
      var host=''; try{host=new URL(api).hostname}catch(e){}
      var pageLocal=/^(localhost|127\.0\.0\.1|\[::1\])$/i.test(location.hostname);
      // The stock localhost:8787 default is only meaningful on the same machine.
      if(!/^(localhost|127\.0\.0\.1|\[::1\])$/i.test(host)||pageLocal)add(api);
    }
  }catch(e){}
  return out;
}
function importProxyTargets(u){
  var bases=importProxyBases(), out=[];
  for(var i=0;i<bases.length;i++){
    out.push({name:i?'server-alt':'server',url:bases[i]+'/fetch?url='+encodeURIComponent(u)});
  }
  return out;
}
async function getPage(url){var clean=url.trim(); var proxies=importProxyTargets(clean).map(function(t){return {name:t.name,json:true,build:function(){return t.url}}}).concat([
  {name:'direct',build:function(u){return u}},
  {name:'jina',build:function(u){return 'https://r.jina.ai/'+u}},
  {name:'allorigins',build:function(u){return 'https://api.allorigins.win/raw?url='+encodeURIComponent(u)}},
  {name:'corsproxy',build:function(u){return 'https://corsproxy.io/?url='+encodeURIComponent(u)}},
  {name:'codetabs',build:function(u){return 'https://api.codetabs.com/v1/proxy?quest='+encodeURIComponent(u)}}
]); var errs=[]; for(var i=0;i<proxies.length;i++){var p=proxies[i],target=p.build(clean); try{var opts=null; if(p.json){var tk=String((syncCfg()||{}).token||''); if(tk)opts={headers:{Authorization:'Bearer '+tk}}} var res=await fetchWithTimeout(target,p.json?35000:20000,opts); if(!res.ok){var d=''; try{var eb=await res.text(),ej=JSON.parse(eb); if(ej&&ej.error)d=' ('+ej.error+')'}catch(e2){} errs.push(p.name+': '+((p.json&&res.status===404)?'route not available':'HTTP '+res.status)+d);continue} var body=await res.text(); if(p.json){var j=null; try{j=JSON.parse(body)}catch(e){} if(!j||typeof j.html!=='string'){errs.push(p.name+': '+((j&&j.error)||'no page returned'));continue} body=j.html} if(!body||body.length<=120){errs.push(p.name+': empty/short');continue} if(looksBlockedPage(body,clean)){errs.push(p.name+': blocked');continue} return {html:body,via:p.name}; }catch(e){errs.push(p.name+': '+(e.name==='AbortError'?'timed out':(e.message||'failed')))}} throw new Error('Could not load page. '+(errs.length?('Relays: '+errs.join('; ')+'. '):'')+'This site may block automated/relay access. Try Paste text, paste from print view, or use image/PDF import (screenshots/save as PDF) with AI if configured.')}
var DEFMODEL='openai/gpt-4o-mini'; function aiCfg(){try{return JSON.parse(localStorage.getItem(SKEY))||{}}catch(e){return {}}} function aiSave(c){try{localStorage.setItem(SKEY,JSON.stringify(c||{}))}catch(e){}}
function importPrefs(){try{return JSON.parse(localStorage.getItem(PKEY))||{}}catch(e){return {}}} function saveImportPrefs(p){try{localStorage.setItem(PKEY,JSON.stringify(p||{}))}catch(e){}}
function parseAiJson(txt){if(Array.isArray(txt))txt=txt.map(function(x){return x&&x.text||''}).join(''); txt=String(txt||'').trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'').trim(); var a=txt.indexOf('{'),b=txt.lastIndexOf('}'); if(a<0||b<a)throw new Error('Model did not return JSON.'); try{return JSON.parse(txt.slice(a,b+1))}catch(e){throw new Error('Model returned unreadable JSON.')}}
async function aiRequest(body){var c=aiCfg(); if(!c.key)throw new Error('Add OpenRouter key in AI settings.'); var res=await fetch('https://openrouter.ai/api/v1/chat/completions',{method:'POST',headers:{'Authorization':'Bearer '+c.key,'Content-Type':'application/json','HTTP-Referer':location.href,'X-Title':'Recipe Box'},body:JSON.stringify(body)}); var raw=await res.text(),data={}; try{data=JSON.parse(raw)}catch(e){} if(!res.ok){var msg=(data.error&&(data.error.message||data.error.code))||('Request failed (HTTP '+res.status+')'); if(res.status===401||res.status===403)msg+=' — check key.'; if(res.status===404)msg+=' — check model.'; throw new Error(msg)} return data}
