var ENC_VERSION=1, ENC_ITER=210000;
function bytesToB64(bytes){var out=''; for(var i=0;i<bytes.length;i+=0x8000){out+=String.fromCharCode.apply(null,bytes.subarray(i,i+0x8000))} return btoa(out)}
