function initSyncUI(){var bs=document.getElementById('btnSync'); if(!bs)return; var c=syncCfg(); var url=document.getElementById('syncUrl'), tok=document.getElementById('syncToken'), auto=document.getElementById('syncAuto'), pass=document.getElementById('syncPass'); function fill(){var c=syncCfg(); if(url)url.value=c.url||'http://localhost:8787/api/recipebox'; if(tok)tok.value=c.token||''; if(pass)pass.value=c.passphrase||''; if(auto)auto.checked=!!c.auto; var enc=document.getElementById('syncEncInfo'); if(enc)enc.textContent=c.passphrase?'Encryption: on (pushes, linked saves and JSON exports are encrypted with your passphrase).':'Encryption: off (data is stored as plain JSON).'} bs.onclick=function(){fill(); setSyncStatus(''); loadVersions(); document.getElementById('dSync').showModal()}; document.getElementById('syncClose').onclick=function(){document.getElementById('dSync').close()}; document.getElementById('syncSaveCfg').onclick=function(){saveSyncCfg({url:(url.value||'').trim(),token:(tok.value||'').trim(),auto:!!auto.checked,passphrase:(pass&&pass.value)||''}); fill(); setSyncStatus('Sync settings saved'+((pass&&pass.value)?' (encryption on)':'')+'.','ok')}; document.getElementById('syncPush').onclick=async function(){saveSyncCfg({url:(url.value||'').trim(),token:(tok.value||'').trim(),auto:!!auto.checked,passphrase:(pass&&pass.value)||''}); fill(); await pushSync(true)}; document.getElementById('syncPull').onclick=async function(){saveSyncCfg({url:(url.value||'').trim(),token:(tok.value||'').trim(),auto:!!auto.checked,passphrase:(pass&&pass.value)||''}); fill(); await pullSync(true)}; async function loadVersions(){var sel=document.getElementById('versionSel'); var st=document.getElementById('versionStatus'); if(!sel)return; sel.innerHTML='<option value="">Loading…</option>'; if(st){st.textContent='Loading server versions…'; st.className='small'} try{var data=await syncRaw(syncVersionsUrl()); var list=(data&&data.versions)||[]; sel.innerHTML=list.length?list.map(function(v){var d=new Date(v.savedAt); return '<option value="'+esc(v.name)+'">'+esc(d.toLocaleString())+' · '+Math.round((v.size||0)/1024)+' KB</option>'}).join(''):'<option value="">No versions yet</option>'; if(st){st.textContent=list.length?(list.length+' version(s) on server (newest first).'):'No versions yet. The server stores the previous dataset each time a changed push occurs.'; st.className='small'}}catch(e){sel.innerHTML='<option value="">Versions unavailable</option>'; if(st){st.textContent=(e.message||String(e))+' — rolling versions need the bundled server.js endpoint.'; st.className='small'}}}
 var vr=document.getElementById('versionRefresh'); if(vr)vr.onclick=loadVersions;
 var vres=document.getElementById('versionRestore'); if(vres)vres.onclick=async function(){var sel=document.getElementById('versionSel'); var name=sel&&sel.value; if(!name){toast('Choose a server version');return} try{var ver=await syncRaw(syncVersionsUrl()+'/'+encodeURIComponent(name)); if(isEncrypted(ver))ver=await decryptPayload(ver); if(!ver||typeof ver!=='object')throw new Error('Invalid version data'); var choice=await openSyncConflict(ver); if(choice==='remote'||choice==='merge'){var merged=choice==='merge'?mergePayloads(payload(),ver):ver; applyPayload(merged); saveLocalOnly(); render(); setSyncStatus(choice==='merge'?'Merged version '+name+' into local data.':'Restored version '+name+'.','ok'); toast(choice==='merge'?'Merged server version':'Restored server version')}}catch(e){setSyncStatus('Version restore failed: '+(e.message||e),'err')}};
 fill();}

