function fmtQty(n){
 if(n==null||!isFinite(n))return '';
 var neg=n<0; n=Math.abs(n);
 var whole=Math.floor(n+1e-9), frac=n-whole;
 if(frac<0.02)return (neg?'-':'')+String(whole);
 if(frac>0.98)return (neg?'-':'')+String(whole+1);
 for(var i=0;i<FRAC_LIST.length;i++){if(Math.abs(frac-FRAC_LIST[i][0])<0.02)return (neg?'-':'')+(whole?String(whole):'')+FRAC_LIST[i][1]}
 var r=Math.round(n*100)/100;
 if(Math.abs(r-Math.round(r))<0.005)return (neg?'-':'')+String(Math.round(r));
 return (neg?'-':'')+String(r).replace(/0+$/,'').replace(/\.$/,'');
}
function singularWord(w){var s=String(w||''); if(!s)return s; if(/ies$/i.test(s)&&s.length>3)return s.slice(0,-3)+'y'; if(/oes$/i.test(s))return s.slice(0,-2); if(/(ches|shes|sses|xes|zes)$/i.test(s))return s.slice(0,-2); if(/s$/i.test(s)&&!/ss$/i.test(s)&&!/us$/i.test(s)&&!/is$/i.test(s))return s.slice(0,-1); return s}
function pluralWord(w){var s=String(w||''); if(!s)return s; if(singularWord(s)!==s)return s; if(/[^aeiou]y$/i.test(s))return s.slice(0,-1)+'ies'; if(/(s|sh|ch|x|z)$/i.test(s))return s+'es'; return s+'s'}
