async function exportSelectedRecipes(){var ids=Object.keys(state.exportSel||{}).filter(function(id){return state.exportSel[id]}); var list=ids.length?state.recipes.filter(function(r){return state.exportSel[r.id]}):[]; if(!list.length){toggleExportSelectionMode(); return} var pick=prompt('Export selected ('+list.length+'): json or markdown','json'); if(!pick)return; var type=pick.toLowerCase(), blob,name; if(type.indexOf('md')===0||type.indexOf('mark')===0){blob=new Blob([list.map(function(r){return toMarkdown(r,1)}).join('\n\n---\n\n')],{type:'text/markdown'}); name='recipes-selected.md'} else {var ex={recipes:list,cats:state.cats,exportedAt:new Date().toISOString()}; ex=await encryptPayload(ex,syncCfg().passphrase); blob=new Blob([JSON.stringify(ex,null,2)],{type:'application/json'}); name='recipes-selected.json'} var a=document.createElement('a'); a.href=URL.createObjectURL(blob); a.download=name; document.body.appendChild(a); a.click(); a.remove(); setTimeout(function(){URL.revokeObjectURL(a.href)},1000); state.exportMode=false; state.exportSel={}; render(); }

function computeCookable(){var have={}; (state.pantry||[]).forEach(function(p){if(p&&p.have)have[pantryKey(p.name)]=1}); var haveKeys=Object.keys(have); if(!haveKeys.length) return {ready:[],almost:[]};
  function hasItem(ing){var k=pantryKey(ing); if(!k)return false; if(have[k])return true; for(var i=0;i<haveKeys.length;i++){if(k.indexOf(haveKeys[i])>-1||haveKeys[i].indexOf(k)>-1)return true} return false}
  var ready=[], almost=[]; (state.recipes||[]).forEach(function(r){var ings=(r.ing||[]).filter(Boolean); if(!ings.length)return; var missing=[]; ings.forEach(function(i){if(!hasItem(i))missing.push(i)}); if(missing.length===0) ready.push({r:r,missing:[]}); else if(missing.length<=Math.max(2,Math.ceil(ings.length*0.35))) almost.push({r:r,missing:missing}); });
  ready.sort(function(a,b){return (b.r.rating||0)-(a.r.rating||0)}); almost.sort(function(a,b){return a.missing.length-b.missing.length}); return {ready:ready.slice(0,12),almost:almost.slice(0,12)} }
function renderCookable(){var el=document.getElementById('cookableList'); var info=document.getElementById('cookableInfo'); if(!el)return; var haveCount=(state.pantry||[]).filter(function(p){return p&&p.have}).length; if(info) info.textContent=haveCount?('Based on '+haveCount+' pantry item(s) marked "have".'):'Mark items as "have" in Pantry to see matches.'; var res=computeCookable(); var h=''; if(res.ready.length){h+='<div class="small" style="margin:4px 0"><strong>Can cook now</strong></div>'+res.ready.map(function(x){return '<div class="itemrow"><div style="flex:1"><strong>'+esc(x.r.title)+'</strong></div><button data-openr="'+esc(x.r.id)+'">Open</button></div>'}).join('')} if(res.almost.length){h+='<div class="small" style="margin:8px 0 4px"><strong>Almost (few missing)</strong></div>'+res.almost.map(function(x){return '<div class="itemrow"><div style="flex:1"><strong>'+esc(x.r.title)+'</strong><div class="small">Missing: '+esc(x.missing.slice(0,3).join(', '))+(x.missing.length>3?'...':'')+'</div></div><button data-openr="'+esc(x.r.id)+'">Open</button></div>'}).join('')} if(!h) h='<div class="small">No matches yet. Add pantry items and mark what you have, or add more recipes.</div>'; el.innerHTML=h; el.onclick=function(e){var b=e.target.closest('button[data-openr]'); if(!b)return; openView(b.dataset.openr)}; }

