function findAllDuplicates(){var groups=[]; var used={}; for(var i=0;i<state.recipes.length;i++){for(var j=i+1;j<state.recipes.length;j++){var a=state.recipes[i],b=state.recipes[j]; var sc=sim(a.title,b.title); var same=(a.title||'').trim().toLowerCase()===(b.title||'').trim().toLowerCase(); if(sc>=0.82||same){groups.push({a:a,b:b,score:sc})}}}
  if(!groups.length){alert('No likely duplicates found.'); return}
  var msg='Possible duplicates:\n\n'+groups.slice(0,20).map(function(g,i){return (i+1)+'. '+g.a.title+'  <->  '+g.b.title+' ('+Math.round(g.score*100)+'%)'}).join('\n')+'\n\nOpen a recipe and use Merge into? or Save to compare/resolve.';
  alert(msg);
}

